ALTER TABLE "Opportunity" ADD COLUMN "matchAttributes" TEXT;
CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "name" TEXT NOT NULL, "isAdmin" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "UserProfile" ("userId" TEXT NOT NULL PRIMARY KEY, "role" TEXT, "goals" TEXT NOT NULL DEFAULT '[]', "industries" TEXT NOT NULL DEFAULT '[]', "businessTypes" TEXT NOT NULL DEFAULT '[]', "budget" TEXT, "team" TEXT, "time" TEXT, "skills" TEXT NOT NULL DEFAULT '[]', "markets" TEXT NOT NULL DEFAULT '[]', "onboardingCompleted" BOOLEAN NOT NULL DEFAULT false, "onboardingSkipped" BOOLEAN NOT NULL DEFAULT false, "onboardingStep" INTEGER NOT NULL DEFAULT 0, "preferences" TEXT NOT NULL DEFAULT '{}', "about" TEXT NOT NULL DEFAULT '', "updatedAt" DATETIME NOT NULL, CONSTRAINT "UserProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Session" ("tokenHash" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "expiresAt" DATETIME NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "SavedOpportunity" ("userId" TEXT NOT NULL, "opportunityId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("userId", "opportunityId"), FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("opportunityId") REFERENCES "Opportunity" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "OpportunityFeedback" ("userId" TEXT NOT NULL, "opportunityId" TEXT NOT NULL, "kind" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("userId", "opportunityId"), FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("opportunityId") REFERENCES "Opportunity" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AuthThrottle" ("key" TEXT NOT NULL PRIMARY KEY, "attempts" INTEGER NOT NULL DEFAULT 0, "expiresAt" DATETIME NOT NULL);
CREATE INDEX "AuthThrottle_expiresAt_idx" ON "AuthThrottle"("expiresAt");
